// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    function setUp() public { c = new DnGmxBatchingManager(); }
    function testFuzz_property(address unauthorizedCaller) public {
        vm.assume(unauthorizedCaller != address(0));
        vm.assume(unauthorizedCaller != c.owner());

        address keeperBefore = c.keeper();

        vm.prank(unauthorizedCaller);
        bool ok = true;
        try c.setKeeper(unauthorizedCaller) {
            ok = true;
        } catch {
            ok = false;
        }

        address keeperAfter = c.keeper();
        assertTrue(keeperBefore == keeperAfter);
    }
}
